"use strict";

exports.memory = function createMemoryStore() {
  const tables = new Map();
  function table(name) {
    if (!tables.has(name)) {
      tables.set(name, []);
    }
    return tables.get(name);
  }
  return {
    async insert(name, row) {
      table(name).push(Object.assign({}, row));
      return { rowsAffected: 1 };
    },
    async select(name, predicate) {
      return table(name).filter(predicate).map((row) => Object.assign({}, row));
    },
    async first(name, predicate) {
      return table(name).find(predicate) || null;
    },
  };
};
